effect.shader:
vec4 ImmCB_0[4];

vec4 u_xlat0;
vec4 u_xlat1;
int u_xlati1;
float u_xlat2;
bool u_xlatb4;
void main()
{
ImmCB_0[0] = vec4(1.0,0.0,0.0,0.0);
ImmCB_0[1] = vec4(0.0,1.0,0.0,0.0);
ImmCB_0[2] = vec4(0.0,0.0,1.0,0.0);
ImmCB_0[3] = vec4(0.0,0.0,0.0,1.0);
    u_xlat0 = texture(clip_mask, acScreenNorm.xy);
    u_xlati1 = int(_clipping_channel);
    u_xlat0.x = dot(u_xlat0, ImmCB_0[u_xlati1]);
    u_xlat2 = (-u_xlat0.x) + 1.0;
    u_xlatb4 = int(_clipping_invert)==1;
    u_xlat0.x = (u_xlatb4) ? u_xlat2 : u_xlat0.x;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    fragColor = u_xlat0.xxxx * u_xlat1;
    return;
}
